"""Custom type converters used by differential-test cases.

Both the implementation under test and the reference oracle import this same
module, so the converters are guaranteed identical on both sides.
"""

import parse


@parse.with_pattern(r"\d+")
def num(text):
    return int(text)


@parse.with_pattern(r"\d+", regex_group_count=0)
def num0(text):
    return int(text)


@parse.with_pattern(r"(meter|kilometer)", regex_group_count=1)
def unit(text):
    return text.strip()


@parse.with_pattern(r"(\d+)-(\d+)-(\d+)", regex_group_count=3)
def ymd(text):
    y, m, d = text.split("-")
    return (int(y), int(m), int(d))


@parse.with_pattern(r"\d+(\.\d+)?", regex_group_count=1)
def number_or_float(text):
    return float(text)


@parse.with_pattern(r"[+-]?\d+")
def signed(text):
    return int(text)


@parse.with_pattern(r"\w+")
def word(text):
    return text


def nopattern(text):
    """A converter with no .pattern attribute at all."""
    return text.upper()


@parse.with_pattern(r"(?:yes|no)")
def yesno(text):
    return text == "yes"


@parse.with_pattern(r"\d+", regex_group_count=None)
def num_none(text):
    return int(text)


@parse.with_pattern(r"((\d+))", regex_group_count=2)
def nested_groups(text):
    return int(text)


def boom(text):
    raise ValueError("boom: %r" % (text,))


boom.pattern = r"\d+"


REGISTRY = {
    "Number": num,
    "Number0": num0,
    "Unit": unit,
    "YMD": ymd,
    "Float": number_or_float,
    "Signed": signed,
    "Word": word,
    "NoPattern": nopattern,
    "YesNo": yesno,
    "NumNone": num_none,
    "Nested": nested_groups,
    "Boom": boom,
    # non-decorated builtins used as converters
    "Int": int,
    "Str": str,
}


def build(names):
    """Build an extra_types mapping from a list of registry names."""
    if not names:
        return None
    return {name: REGISTRY[name] for name in names}

