"""Differential-test driver.

Reads a JSON list of cases and prints one canonical, deterministic line per
observation. Run once with the implementation under test on sys.path and once
with the reference oracle; diff the two outputs.

Case schema (all keys optional except ``format``)::

    {
      "format": "...",
      "string": "...",              # omitted -> only the expression is probed
      "types": ["Number", ...],     # names from converters.REGISTRY
      "case_sensitive": false,
      "pos": 0,
      "endpos": null,
      "id": "free-form label"
    }
"""

import json
import sys

import parse

import converters


def canon(value):
    """Canonical, ordering-stable repr of a parse result value."""
    if isinstance(value, dict):
        return "{%s}" % ", ".join(
            "%r: %s" % (k, canon(v)) for k, v in sorted(value.items(), key=lambda kv: repr(kv[0]))
        )
    if isinstance(value, tuple):
        return "(%s)" % ", ".join(canon(v) for v in value)
    if isinstance(value, list):
        return "[%s]" % ", ".join(canon(v) for v in value)
    return repr(value)


def canon_result(r):
    if r is None:
        return "None"
    if isinstance(r, parse.Result):
        return "Result fixed=%s named=%s spans=%s" % (
            canon(r.fixed),
            canon(r.named),
            canon(r.spans),
        )
    if isinstance(r, parse.Match):
        return "Match %s" % canon_result(r.evaluate_result())
    return "?? %r" % (r,)


def guarded(fn):
    try:
        return fn()
    except Exception as e:  # noqa: BLE001 - we are comparing failure modes too
        return "EXC %s: %s" % (type(e).__name__, e)


def emit(case_id, label, value):
    print("%s\t%s\t%s" % (case_id, label, value))


def probe(case, idx):
    case_id = "%d:%s" % (idx, case.get("id", ""))
    fmt = case["format"]
    types = converters.build(case.get("types"))
    cs = case.get("case_sensitive", False)

    def make():
        return parse.Parser(fmt, extra_types=types, case_sensitive=cs)

    p = guarded(make)
    if isinstance(p, str):
        emit(case_id, "parser", p)
        return
    emit(case_id, "expression", repr(p._expression))
    emit(case_id, "named_fields", canon(p.named_fields))
    emit(case_id, "fixed_fields", canon(p.fixed_fields))
    emit(case_id, "group_index", repr(p._group_index))
    emit(
        case_id,
        "conversions",
        canon(sorted((repr(k) for k in p._type_conversions), key=str)),
    )
    emit(case_id, "repr", repr(p))
    emit(case_id, "match_re", guarded(lambda: repr(p._match_re.pattern)))

    if "string" not in case:
        return
    s = case["string"]
    pos = case.get("pos", 0)
    endpos = case.get("endpos", None)

    emit(case_id, "parse", guarded(lambda: canon_result(p.parse(s))))
    emit(
        case_id,
        "parse_lazy",
        guarded(lambda: canon_result(p.parse(s, evaluate_result=False))),
    )
    emit(case_id, "search", guarded(lambda: canon_result(p.search(s, pos, endpos))))
    emit(
        case_id,
        "search_lazy",
        guarded(
            lambda: canon_result(p.search(s, pos, endpos, evaluate_result=False))
        ),
    )
    emit(
        case_id,
        "findall",
        guarded(
            lambda: canon([canon_result(r) for r in p.findall(s, pos, endpos)][:25])
        ),
    )
    # module level entry points (fresh parser each time)
    emit(
        case_id,
        "mod_parse",
        guarded(
            lambda: canon_result(
                parse.parse(fmt, s, extra_types=types, case_sensitive=cs)
            )
        ),
    )
    emit(
        case_id,
        "mod_search",
        guarded(
            lambda: canon_result(
                parse.search(
                    fmt, s, pos, endpos, extra_types=types, case_sensitive=cs
                )
            )
        ),
    )
    emit(
        case_id,
        "mod_findall",
        guarded(
            lambda: canon(
                [
                    canon_result(r)
                    for r in parse.findall(
                        fmt, s, pos, endpos, extra_types=types, case_sensitive=cs
                    )
                ][:25]
            )
        ),
    )


def main():
    cases = []
    for path in sys.argv[1:]:
        with open(path) as f:
            cases.extend(json.load(f))
    for idx, case in enumerate(cases):
        try:
            probe(case, idx)
        except Exception as e:  # noqa: BLE001
            emit("%d:%s" % (idx, case.get("id", "")), "FATAL", "%s: %s" % (type(e).__name__, e))


if __name__ == "__main__":
    main()

